INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q6', 'GATE', 'CS', '', 2024, '1', 6, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'In the given text, the blanks are numbered (i)-(iv). Select the best match for all the blanks. Steve was advised to keep his head (i) before heading (ii) to bat; for, while he had a head (iii) batting, he could only do so with a cool head s (iv) his shoulders.', ARRAY[ARRAY['(i) down (ii) down (iii) on (iv) for'], ARRAY['(i) on (ii) down (iii) for (iv) on'], ARRAY['(i) down (ii) out (iii) for (iv) on'], ARRAY['(i) on (ii) out (iii) on (iv) for']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q7', 'GATE', 'CS', '', 2024, '1', 7, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A rectangular paper sheet of dimensions 54 cm � 4 cm is taken. The two longer edges of the sheet are joined together to create a cylindrical tube. A cube whose surface area is equal to the area of the sheet is also taken. Then, the ratio of the volume of the cylindrical tube to the volume of the cube is', ARRAY[ARRAY['1/'], ARRAY['2/'], ARRAY['3/'], ARRAY['4/']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q8', 'GATE', 'CS', '', 2024, '1', 8, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'The pie chart presents the percentage contribution of different macronutrients to a typical 2,000 kcal diet of a person. Macronutrient energy contribution Trans Carbohydrates fat 35% 5% Saturated fat 20% Unsaturated fat 20% Proteins 20% The typical energy density (kcal/g) of these macronutrients is given in the table. Macronutrient Energy density (kcal/g) Carbohydrates 4 Proteins 4 Unsaturated fat 9 Saturated fat 9 Trans fat 9 The total fat (all three types), in grams, this person consumes is', ARRAY[ARRAY['44.4'], ARRAY['77.8'], ARRAY['100'], ARRAY['3,600']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
